{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Loteprednol etabonate, a soft corticosteroid with a 17-ester modification, had very low oral bioavailability after a 40-mg oral dose in healthy volunteers, showing that steroid modifications designed to limit systemic exposure can drive F well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Mometasone, a halogenated/esterified corticosteroid, has reported oral bioavailability <1%, demonstrating that certain corticosteroid structural modifications produce very low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Prednisolone, the closest high-similarity analogue, shows complete systemic availability in humans, but it lacks the 16,17-acetal/cyclohexyl motif of the query; this supports high F only if the acetal does not introduce first-pass liability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C37"],
      "claim": "Deflazacort, which contains a 16,17-fused heterocycle, has 68% absolute oral bioavailability, suggesting that fused rings at this position do not necessarily preclude high F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C53"],
      "claim": "17-BMP has oral bioavailability 41%, above the 20% threshold, but is lower than simple corticosteroids and reflects increased first-pass metabolism with steroid ester modifications.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a corticosteroid with a 16,17-cyclohexyl acetal (desisobutyrylciclesonide-like soft steroid). Although simple corticosteroids such as prednisolone, methylprednisolone, hydrocortisone, and dexamethasone have high oral bioavailability, they lack the acetal/soft-steroid modification. The low-bioavailability soft steroids loteprednol etabonate and mometasone are mechanistically more relevant to this structural class, where extensive first-pass metabolism and high lipophilicity limit systemic exposure. The 16,17-acetal/cyclohexyl motif is expected to push F below 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability data for desisobutyrylciclesonide or ciclesonide in the supplied evidence.",
    "No analogue with the exact 16,17-cyclohexyl acetal is present; closest heterocycle-containing analogue (deflazacort) has high F.",
    "Acid lability of the dioxolane ring and its impact on oral absorption is uncertain.",
    "First-pass metabolism and transporter effects for the query are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

